#!/usr/bin/env node
// Assert that an update artifact was signed by the key the shipped app trusts.
//
// The updater verifies a download against `plugins.updater.pubkey` compiled
// into the app. If CI ever signs with a different private key - a rotated
// secret, a mistyped one, a second keypair generated by mistake - every stage
// of the release still passes: the bundle builds, Authenticode verifies, the
// manifest is well-formed. The failure lands on users, silently, as an update
// that downloads and is then rejected forever. This is the cheap insurance.
//
// Both minisign blobs carry an 8-byte key id, so this needs no crypto: decode
// each, compare the ids. It does not re-verify the signature itself, which
// Tauri already produced with that key.
//
//   node check-updater-key.mjs <tauri.conf.json> <artifact.sig>

import { readFileSync } from "node:fs";

/** Decoded payload sizes: 2-byte algorithm tag + 8-byte key id + the key/sig. */
const PUBKEY_BYTES = 42; // + 32-byte public key
const SIGNATURE_BYTES = 74; // + 64-byte signature

/**
 * Pull the key id out of a base64-wrapped minisign file.
 *
 * The line carrying the key id is selected BY DECODED LENGTH, not by position.
 * A public key file has two lines (comment, payload) but a signature has four:
 * comment, the signature proper, a trusted comment, then a global signature
 * over it. Taking the last line - which is what this did first - reads the
 * global signature, whose bytes 2..10 are signature material that will never
 * match a key id, so the check failed closed on every correctly signed
 * artifact.
 */
function keyId(base64File, label) {
	const decoded = Buffer.from(base64File.trim(), "base64").toString("utf8");
	for (const line of decoded.split("\n").map((l) => l.trim())) {
		if (!line || !/^[A-Za-z0-9+/]+={0,2}$/.test(line)) continue;
		const bytes = Buffer.from(line, "base64");
		if (bytes.length === PUBKEY_BYTES || bytes.length === SIGNATURE_BYTES) {
			return bytes.subarray(2, 10).toString("hex");
		}
	}
	throw new Error(
		`${label}: no ${PUBKEY_BYTES}- or ${SIGNATURE_BYTES}-byte payload line found`,
	);
}

const [confPath, sigPath] = process.argv.slice(2);
if (!confPath || !sigPath) {
	console.error("usage: check-updater-key.mjs <tauri.conf.json> <artifact.sig>");
	process.exit(1);
}

const conf = JSON.parse(readFileSync(confPath, "utf8"));
const pubkey = conf?.plugins?.updater?.pubkey;
if (!pubkey) {
	console.error(`No plugins.updater.pubkey in ${confPath}.`);
	process.exit(1);
}

let shipped;
let signed;
try {
	shipped = keyId(pubkey, "pubkey");
	signed = keyId(readFileSync(sigPath, "utf8"), "signature");
} catch (err) {
	console.error(`Could not read a key id: ${err.message}`);
	process.exit(1);
}

if (shipped !== signed) {
	console.error(
		`Updater key mismatch: the app trusts key ${shipped}, but ${sigPath} was ` +
			`signed by ${signed}. Installed clients would reject this update. Check ` +
			"TAURI_SIGNING_PRIVATE_KEY against plugins.updater.pubkey.",
	);
	process.exit(1);
}

console.log(`Updater key OK: signed by ${signed}, which the app trusts.`);
